 LogMatch m;string folder,key,saved;bool had,restored;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("LogEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<LogMatch>("TruckLogRolling");m=FindAnyObjectByType<LogMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);m.SetupScreen();m.setup.count=4;m.NormalizeSetup();m.AllBots();Check(m.StartMatch(),"actual vendor log equilibrium fixture starts");m.enabled=false;foreach(var f in m.fighters){f.truck.Power(false);f.truck.body.isKinematic=true;f.gameObject.SetActive(false);}Time.timeScale=5;float start=Time.time,next=0;float low=float.MaxValue,high=float.MinValue,peak=0;while(Time.time-start<20&&errors==0){var p=m.log.position;peak=Mathf.Max(peak,m.log.linearVelocity.magnitude);if(Time.time-start>12){low=Mathf.Min(low,p.y);high=Mathf.Max(high,p.y);}if(Time.realtimeSinceStartup>next){File.WriteAllText(folder+"/progress.txt",log+"EQUILIBRIUM y="+p.y+" velocity="+m.log.linearVelocity+" wet="+m.buoyancy.WetTriangles+" steps="+m.buoyancy.Steps);next=Time.realtimeSinceStartup+2;}yield return null;}Check(!float.IsNaN(m.log.position.y)&&low> -2&&high<2&&high-low<.8f&&peak<15&&m.buoyancy.Steps>100,"owned Floating Entities solver supports real metre hull/mass without NaN, runaway forces or hidden platform");log.AppendLine("EQUILIBRIUM low="+low+" high="+high+" peakVelocity="+peak+" wetTriangles="+m.buoyancy.WetTriangles+" steps="+m.buoyancy.Steps);m.enabled=true;m.SetupScreen();Time.timeScale=1;
 for(int test=0;test<3&&errors==0;test++){m.setup.count=test==0?2:4;m.NormalizeSetup();m.AllBots();for(int i=0;i<m.setup.count;i++)m.setup.players[i].difficulty=(BowlingDifficulty)test;Check(m.StartMatch(),"full physical Log match starts difficulty="+test);Time.timeScale=7;float deadline=Time.realtimeSinceStartup+1000;next=0;bool pause=false,replay=false;int braces=0;float speed=0;while(!m.Finished&&Time.realtimeSinceStartup<deadline&&errors<10){for(int i=0;i<m.setup.count;i++){braces=Mathf.Max(braces,m.fighters[i].Braces);speed=Mathf.Max(speed,m.fighters[i].truck.body.linearVelocity.magnitude);}replay|=m.Stage==LogStage.Replay&&m.replay.Playing;if(!pause&&m.Stage==LogStage.Balance&&m.Clock>1){m.Pause();var p=m.log.position;var v=m.log.linearVelocity;int heat=m.rules.Heat;yield return new WaitForSecondsRealtime(.15f);Check(p==m.log.position&&v==m.log.linearVelocity&&heat==m.rules.Heat,"pause preserves actual buoyant log/velocity/heat");if(test==1){m.menus.Show(SportsEventScreen.Play);yield return new WaitForSecondsRealtime(.2f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1440,900),new Vector2Int(1280,960),new Vector2Int(2560,1080)}){SportsControlledCapture.Save(m,size.x,size.y,folder+"/final-log-four-players-"+size.x+"x"+size.y+"-controlled-ui.png");yield return null;}m.menus.Show(SportsEventScreen.Pause);}m.Resume();Time.timeScale=7;pause=true;}if(Time.realtimeSinceStartup>next){File.WriteAllText(folder+"/progress.txt",log+"LIVE difficulty="+test+" heat="+m.rules.Heat+" stage="+m.Stage+" time="+m.Clock+" wins="+string.Join(",",m.rules.wins)+" log="+m.log.position+" roll="+m.MaximumRoll+" falls="+m.Falls+" contacts="+m.ContactCount);next=Time.realtimeSinceStartup+2;}yield return null;}Check(m.Finished&&m.rules.Winner>=0&&m.rules.wins[m.rules.Winner]==5,"complete first-to-five physical match difficulty="+test);Check(m.Falls>0&&replay&&speed>1&&m.MaximumRoll>.1f,"actual truck motion, rotating log, water falls and recorded decisive replays");log.AppendLine("MATCH difficulty="+test+" winner="+m.rules.Winner+" heats="+m.rules.Heat+" wins="+string.Join(",",m.rules.wins)+" draws="+m.Draws+" falls="+m.Falls+" contacts="+m.ContactCount+" roll="+m.MaximumRoll+" peakTruckSpeed="+speed+" braces="+braces);Time.timeScale=1;m.SetupScreen();}
 if(errors==0){m.setup.count=4;m.NormalizeSetup();m.AllBots();Check(m.StartMatch()&&m.rules.Heat==1&&m.rules.wins[0]==0&&m.Falls==0,"rematch restores every truck, log and authoritative score");m.SetupScreen();}Restore();log.AppendLine("ERRORS="+errors+". Actual vendor buoyancy and NWH/PhysX match simulation, no injected results. No human/hardware or rendered performance claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.enabled=true;m.SetupScreen();}if(key!=null){if(had)SportsPrefs.SetString(key,saved);else SportsPrefs.DeleteKey(key);SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
